task.solution:
public class Main {
    static int digits(int n) {
        if (n == 0) {
            return 1;
        }
        int count = 0;
        while (n > 0) {
            n /= 10;
            count++;
        }
        return count;
    }

    public static void main(String[] args) {
        System.out.println(digits(9876) + " " + digits(0) + " " + digits(5));
    }
}

